package cn.yuanxin.mvp.web.sms;

import java.time.Instant;
import java.util.Optional;

/**
 * 阿里云短信状态存储端口（challenge 生命周期、一次性核销、尝试上限、三窗口节流）。
 *
 * <p><b>为什么抽端口</b>：{@link AliyunSmsCodeProvider} 只负责"生成随机码、调远端、
 * 按 {@code Code==OK} 判定受理、把失败映射为 HTTP"，把<b>状态</b>（challenge 与节流计数）
 * 留给本端口。由此得到两个实现：{@link InMemorySmsStateStore}（逐字保留既有进程内语义，
 * 仅供隔离测试 / {@code app.state.provider=memory}）与 {@link RedisSmsStateStore}
 * （跨实例一致、重启不丢，{@code app.state.provider=redis}）。</p>
 *
 * <p><b>为什么 {@code reserveSend} 需要配套的 {@code releaseSend}</b>：跨实例无法用进程内锁把
 * "预检 → 远端发送 → 记录受理" 串行化，因此 Redis 实现改为<b>原子预留 + 失败补偿</b>：
 * {@link #reserveSend(String, Instant)} 用一个 Lua 原子地检查并占用三个窗口名额（并发下绝不超发），
 * 远端发送<b>未被受理</b>时由 {@link #releaseSend(SendReservation, boolean)} 用另一个 Lua 原子回退。
 * 这是相对旧实现的一处<b>有意的语义精化</b>：稳态计数仍等于受理成功的发送数，差别只在
 * "发送失败瞬间名额被短暂占用"，方向更严格（见 {@code backend/handoffs/B-redis-state-migration.md} §4）。</p>
 *
 * <p><b>业务判定不用异常通道</b>：验证码错误 / 过期 / 超上限一律以 {@link Optional#empty()}
 * 表达；限流以 {@link SendReservation#granted()} 为 false 的正常返回值表达。存储后端故障才由
 * {@link cn.yuanxin.mvp.web.state.RedisFailures} 翻译为 503，绝不被误判为"验证码错误"。</p>
 *
 * <p><b>脱敏</b>：手机号只在值中出现（核销成功必须返回它才能建会话），绝不出现在键、日志或异常
 * 消息里；验证码明文绝不落存储（Redis 存 {@code sha256(code + "|" + challengeId)}）。</p>
 */
public interface SmsStateStore {

    /**
     * 原子地检查并按需预留三个节流窗口（分钟 / 小时 / 日，UTC+8 自然边界）。
     *
     * @return {@link SendReservation#granted()} 为 true 表示已预留（内存实现同时持有该手机号的
     *         条带锁与容量名额，必须最终调用 {@link #releaseSend}）；否则为限流，携带 retry-after 秒数
     */
    SendReservation reserveSend(String phone, Instant now);

    /**
     * 远端发送<b>已被平台受理</b>后记录（Redis 实现的预留计数即受理计数，故为 no-op；
     * 内存实现记录 {@code acceptedSends} 历史）。
     */
    void commitSend(SendReservation reservation, Instant now);

    /**
     * 释放一次预留：内存实现释放条带锁与容量名额；Redis 实现在 {@code accepted} 为 false 时
     * 原子回退三个窗口计数（预留 + 失败补偿），为 true 时不做任何事。
     */
    void releaseSend(SendReservation reservation, boolean accepted);

    /**
     * 创建 challenge（已持有 {@code reservation}）。Redis 实现写哈希 + TTL 一次完成且仅当不存在；
     * 内存实现写入进程内 map（容量名额已在 {@link #reserveSend} 预留）。
     *
     * @param challengeId 服务端生成的 challengeId（同时作为验证码摘要的盐）
     * @param phone       手机号（唯一 PII，值中存储）
     * @param code        明文验证码（内存实现直接存、Redis 实现只存摘要；<b>绝不</b>入日志）
     */
    void createChallenge(String challengeId, String phone, String code, Instant now, int ttlSeconds);

    /**
     * 原子地核销：不存在 / 已过期 / 超尝试上限 / 摘要不匹配 ⇒ {@link Optional#empty()}；
     * 匹配 ⇒ 一次性删除并返回手机号。
     */
    Optional<String> consumeChallenge(String challengeId, String code, Instant now, int maxAttempts);

    /**
     * 一次发送预留的结果。
     *
     * <p>普通 Java 对象而非 record：{@code handle} 是实现私有句柄（内存实现为条带锁，
     * Redis 实现为三个窗口键），provider 只读取 {@link #granted()} / {@link #retryAfterSeconds()}。</p>
     */
    final class SendReservation {

        private final String phone;
        private final boolean granted;
        private final long retryAfterSeconds;
        private final Object handle;

        private SendReservation(String phone, boolean granted, long retryAfterSeconds, Object handle) {
            this.phone = phone;
            this.granted = granted;
            this.retryAfterSeconds = retryAfterSeconds;
            this.handle = handle;
        }

        static SendReservation granted(String phone, Object handle) {
            return new SendReservation(phone, true, 0L, handle);
        }

        static SendReservation throttled(long retryAfterSeconds) {
            return new SendReservation(null, false, Math.max(1L, retryAfterSeconds), null);
        }

        /** 是否已预留（false 表示被本地节流拒绝，应映射为 429）。 */
        public boolean granted() {
            return granted;
        }

        /** 被拒绝时建议的 retry-after 秒数；已预留时为 0。 */
        public long retryAfterSeconds() {
            return retryAfterSeconds;
        }

        String phone() {
            return phone;
        }

        Object handle() {
            return handle;
        }
    }
}

package cn.yuanxin.mvp.web.sms;

import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

/**
 * 短信节流窗口的 UTC+8 自然边界归一（分钟 / 小时 / 日）。
 *
 * <p>两个后端共用本类，保证"内存实现"与"Redis 实现"对窗口边界、桶名与剩余时间的理解
 * <b>逐字一致</b>；若不共用，跨实例窗口错位与内存/Redis 行为漂移都会难以察觉。</p>
 *
 * <p>内存实现仍按 {@code sameMinute/sameHour/sameDay} 对历史时间戳过滤（逐字保留旧语义）；
 * Redis 实现用本类给出的桶名（如 {@code 202609141230}）构造计数键。两者对固定自然窗口等价。</p>
 */
final class SmsThrottleWindows {

    /** 官方短信验证码频控窗口按 UTC+8 自然分钟/小时/日。 */
    static final ZoneOffset CN_OFFSET = ZoneOffset.ofHours(8);

    /**
     * 计数键 TTL 相对窗口边界的余量（秒）：容忍多实例之间的轻微时钟偏移。
     * 桶名按各自时钟归一，键多活几秒不会造成跨桶串读。
     */
    static final long TTL_MARGIN_SECONDS = 5L;

    private static final DateTimeFormatter MINUTE_BUCKET = DateTimeFormatter.ofPattern("yyyyMMddHHmm");
    private static final DateTimeFormatter HOUR_BUCKET = DateTimeFormatter.ofPattern("yyyyMMddHH");
    private static final DateTimeFormatter DAY_BUCKET = DateTimeFormatter.ofPattern("yyyyMMdd");

    private SmsThrottleWindows() {
    }

    /** 三个窗口的桶名、键 TTL 与耗尽时的 retry-after（全部按 UTC+8 自然边界）。 */
    record Snapshot(String minuteBucket, String hourBucket, String dayBucket,
                    long minuteTtlSeconds, long hourTtlSeconds, long dayTtlSeconds,
                    long minuteRetryAfterSeconds, long hourRetryAfterSeconds, long dayRetryAfterSeconds) {
    }

    static Snapshot compute(Instant now) {
        ZonedDateTime nowCn = now.atZone(CN_OFFSET);
        long retryMinute = secondsToNextMinute(nowCn);
        long retryHour = secondsToNextHour(nowCn);
        long retryDay = secondsToNextDay(nowCn);
        return new Snapshot(
                nowCn.format(MINUTE_BUCKET), nowCn.format(HOUR_BUCKET), nowCn.format(DAY_BUCKET),
                retryMinute + TTL_MARGIN_SECONDS, retryHour + TTL_MARGIN_SECONDS,
                retryDay + TTL_MARGIN_SECONDS,
                retryMinute, retryHour, retryDay);
    }

    static boolean sameMinute(Instant instant, ZonedDateTime nowCn) {
        return instant.atZone(CN_OFFSET).truncatedTo(ChronoUnit.MINUTES)
                .equals(nowCn.truncatedTo(ChronoUnit.MINUTES));
    }

    static boolean sameHour(Instant instant, ZonedDateTime nowCn) {
        return instant.atZone(CN_OFFSET).truncatedTo(ChronoUnit.HOURS)
                .equals(nowCn.truncatedTo(ChronoUnit.HOURS));
    }

    static boolean sameDay(Instant instant, ZonedDateTime nowCn) {
        return instant.atZone(CN_OFFSET).toLocalDate().equals(nowCn.toLocalDate());
    }

    static long secondsToNextMinute(ZonedDateTime nowCn) {
        return Math.max(1, 60L - nowCn.getSecond());
    }

    static long secondsToNextHour(ZonedDateTime nowCn) {
        long elapsed = nowCn.getMinute() * 60L + nowCn.getSecond();
        return Math.max(1, 3600L - elapsed);
    }

    static long secondsToNextDay(ZonedDateTime nowCn) {
        ZonedDateTime nextDay = nowCn.toLocalDate().plusDays(1).atStartOfDay(CN_OFFSET);
        return Math.max(1, Duration.between(nowCn, nextDay).getSeconds());
    }
}

package cn.yuanxin.mvp.web.sms;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;

import java.time.Duration;
import java.time.Instant;
import java.time.ZonedDateTime;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

/**
 * 进程内短信状态存储（{@code app.state.provider=memory}，默认；仅供隔离测试与 doubles）。
 *
 * <p><b>逐字保留迁移前的内存语义</b>（从 {@code AliyunSmsCodeProvider} 原样搬入，仅反射可观测面
 * 改为指向本类）：{@code maxChallenges}/{@code maxTrackedPhones} 容量上限、机会式回收
 * {@code pruneExpiredChallenges}/{@code pruneStaleAcceptedSends}、以及
 * {@code ReentrantLock[64]} 条带锁保护的"预检 → 远端发送 → 记录"临界区。</p>
 *
 * <p><b>条带锁</b>：{@link #reserveSend} 取得该手机号条带锁并一直持有到
 * {@link #releaseSend}；因此同一手机号的"预检 → 远端发送 → 记录受理"整体串行，
 * 并发请求不会全部通过预检后各发一条<b>计费</b>短信。跨实例下该锁无效——那正是
 * {@link RedisSmsStateStore} 使用原子预留 + 失败补偿的原因。</p>
 *
 * <p><b>已知局限（如实披露）</b>：状态为进程内 {@code ConcurrentHashMap} ⇒ 应用重启即失效、
 * 多实例不共享。生产必须用 Redis（{@code StateStoreConfigGuard} 在生产 + real 下拒绝 memory）。</p>
 */
public final class InMemorySmsStateStore implements SmsStateStore {

    /** 按手机号分条带的固定锁数量；不同条带基本并行，同条带串行。 */
    static final int SEND_STRIPES = 64;

    /** 未核销 challenge 的默认容量上限；超限拒绝新签发（fail-closed），不丢有效 challenge。 */
    public static final int DEFAULT_MAX_CHALLENGES = 10_000;

    /** 节流历史中 phone key 的默认数量上限；超限拒绝新签发（fail-closed）。 */
    public static final int DEFAULT_MAX_TRACKED_PHONES = 10_000;

    /** 节流历史的保留窗口；超出即剪枝，用于回收 phone key。 */
    static final Duration ACCEPTED_SEND_RETENTION = Duration.ofDays(2);

    private final SmsRiskProperties risk;
    private final Map<String, Challenge> challenges = new ConcurrentHashMap<>();
    private final Map<String, Deque<Instant>> acceptedSends = new ConcurrentHashMap<>();
    private final ReentrantLock[] sendStripes = new ReentrantLock[SEND_STRIPES];
    private final int maxChallenges;
    private final int maxTrackedPhones;
    private final Object capacityMonitor = new Object();
    private int reservedChallenges;

    public InMemorySmsStateStore(SmsRiskProperties risk) {
        this(risk, DEFAULT_MAX_CHALLENGES, DEFAULT_MAX_TRACKED_PHONES);
    }

    public InMemorySmsStateStore(SmsRiskProperties risk, int maxChallenges, int maxTrackedPhones) {
        if (maxChallenges <= 0 || maxTrackedPhones <= 0) {
            throw new IllegalArgumentException("capacity limits must be positive");
        }
        this.risk = risk;
        this.maxChallenges = maxChallenges;
        this.maxTrackedPhones = maxTrackedPhones;
        for (int i = 0; i < SEND_STRIPES; i++) {
            sendStripes[i] = new ReentrantLock();
        }
    }

    @Override
    public SendReservation reserveSend(String phone, Instant now) {
        ReentrantLock stripe = stripeFor(phone);
        stripe.lock();
        try {
            long throttleRetryAfter = throttleRetryAfterSeconds(phone, now);
            if (throttleRetryAfter > 0) {
                stripe.unlock();
                return SendReservation.throttled(throttleRetryAfter);
            }
            // 有界内存检查在发送之前完成，避免"已计费发送后才因容量拒绝"。
            ensureTrackedPhoneCapacity(phone, now);
            reserveChallengeSlot(now);
            return SendReservation.granted(phone, stripe);
        } catch (RuntimeException ex) {
            stripe.unlock();
            throw ex;
        }
    }

    @Override
    public void commitSend(SendReservation reservation, Instant now) {
        // 只统计已受理发送；失败/被节流拒绝的请求绝不计入。
        recordAcceptedSend(reservation.phone(), now);
    }

    @Override
    public void releaseSend(SendReservation reservation, boolean accepted) {
        releaseChallengeReservation();
        stripeFor(reservation.phone()).unlock();
    }

    @Override
    public void createChallenge(String challengeId, String phone, String code, Instant now, int ttlSeconds) {
        // 容量名额已在 reserveSend 预留；发送成功即转为已存 challenge。
        challenges.put(challengeId, new Challenge(phone, code, now.plusSeconds(ttlSeconds)));
    }

    @Override
    public Optional<String> consumeChallenge(String challengeId, String code, Instant now, int maxAttempts) {
        // 机会式清理已过期条目，避免过期未核销的 challenge 永不回收。
        pruneExpiredChallenges(now);
        Challenge challenge = challenges.get(challengeId);
        if (challenge == null) {
            return Optional.empty();
        }
        synchronized (challenge) {
            if (challenge.consumed) {
                return Optional.empty();
            }
            if (now.isAfter(challenge.expiresAt)) {
                challenges.remove(challengeId, challenge);
                return Optional.empty();
            }
            if (challenge.attempts.get() >= maxAttempts) {
                // 尝试次数已耗尽：立即回收，不再占用内存。
                challenges.remove(challengeId, challenge);
                return Optional.empty();
            }
            boolean matches = code != null && java.security.MessageDigest.isEqual(
                    challenge.code.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                    code.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            if (!matches) {
                if (challenge.attempts.incrementAndGet() >= maxAttempts) {
                    // 本次错误尝试后达到上限：立即回收。
                    challenges.remove(challengeId, challenge);
                }
                return Optional.empty();
            }
            challenge.consumed = true;
            challenges.remove(challengeId, challenge);
            return Optional.of(challenge.phone);
        }
    }

    private ReentrantLock stripeFor(String phone) {
        return sendStripes[Math.floorMod(phone.hashCode(), SEND_STRIPES)];
    }

    private long throttleRetryAfterSeconds(String phone, Instant now) {
        Deque<Instant> history = acceptedSends.get(phone);
        if (history == null) {
            return 0;
        }
        ZonedDateTime nowCn = now.atZone(SmsThrottleWindows.CN_OFFSET);
        long retryAfter = 0;
        synchronized (history) {
            long inMinute = history.stream()
                    .filter(t -> SmsThrottleWindows.sameMinute(t, nowCn)).count();
            long inHour = history.stream()
                    .filter(t -> SmsThrottleWindows.sameHour(t, nowCn)).count();
            long inDay = history.stream()
                    .filter(t -> SmsThrottleWindows.sameDay(t, nowCn)).count();
            if (inMinute >= risk.maxPerMinute()) {
                retryAfter = Math.max(retryAfter, SmsThrottleWindows.secondsToNextMinute(nowCn));
            }
            if (inHour >= risk.maxPerHour()) {
                retryAfter = Math.max(retryAfter, SmsThrottleWindows.secondsToNextHour(nowCn));
            }
            if (inDay >= risk.maxPerDay()) {
                retryAfter = Math.max(retryAfter, SmsThrottleWindows.secondsToNextDay(nowCn));
            }
        }
        return retryAfter;
    }

    /** 移除已过期 challenge（机会式，O(n)，n 受 {@code maxChallenges} 约束）。 */
    private void pruneExpiredChallenges(Instant now) {
        challenges.entrySet().removeIf(entry -> now.isAfter(entry.getValue().expiresAt));
    }

    /**
     * 在发送前<b>预留</b>一个 challenge 名额：先清理过期，仍超上限则拒绝新签发。
     * 预留计数保证跨条带并发下容量不被突破；无论发送成败，最终都须
     * {@link #releaseSend} 释放预留（成功时名额转为已存 challenge）。
     */
    private void reserveChallengeSlot(Instant now) {
        synchronized (capacityMonitor) {
            pruneExpiredChallenges(now);
            if (challenges.size() + reservedChallenges >= maxChallenges) {
                throw dependencyUnavailable(
                        "local sms challenge capacity reached (max=" + maxChallenges + "); retry later",
                        "capacity guard prevents unbounded memory; no valid challenge was dropped");
            }
            reservedChallenges++;
        }
    }

    private void releaseChallengeReservation() {
        synchronized (capacityMonitor) {
            reservedChallenges--;
        }
    }

    /**
     * 发送前检查该手机号的节流历史 key 是否可容纳：先机会式剪枝并回收历史为空的 key，
     * 仍达上限则拒绝新签发（fail-closed；绝不静默丢弃既有节流历史，否则会放宽风控）。
     */
    private void ensureTrackedPhoneCapacity(String phone, Instant now) {
        if (acceptedSends.containsKey(phone)) {
            return;
        }
        pruneStaleAcceptedSends(now);
        if (acceptedSends.size() >= maxTrackedPhones) {
            throw dependencyUnavailable(
                    "local sms tracking capacity reached (max=" + maxTrackedPhones + "); retry later",
                    "fail-closed to preserve throttle integrity; retry later");
        }
    }

    /**
     * 机会式剪枝：移除超过保留窗口的历史；某 phone 的历史为空则移除该 key。
     * 用 {@code computeIfPresent} 与 {@link #recordAcceptedSend} 的 {@code compute} 互斥，
     * 避免与并发记录竞争导致历史丢失。
     */
    private void pruneStaleAcceptedSends(Instant now) {
        Instant cutoff = now.minus(ACCEPTED_SEND_RETENTION);
        for (String phone : acceptedSends.keySet()) {
            acceptedSends.computeIfPresent(phone, (key, history) -> {
                synchronized (history) {
                    while (!history.isEmpty() && history.peekFirst().isBefore(cutoff)) {
                        history.pollFirst();
                    }
                }
                return history.isEmpty() ? null : history;
            });
        }
    }

    private void recordAcceptedSend(String phone, Instant at) {
        Instant cutoff = at.minus(ACCEPTED_SEND_RETENTION);
        acceptedSends.compute(phone, (key, existing) -> {
            Deque<Instant> history = existing == null ? new ArrayDeque<>() : existing;
            synchronized (history) {
                history.addLast(at);
                while (!history.isEmpty() && history.peekFirst().isBefore(cutoff)) {
                    history.pollFirst();
                }
            }
            return history;
        });
    }

    private static ApiException dependencyUnavailable(String detail, String guidance) {
        return new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                "sms provider unavailable: " + detail + "; " + guidance);
    }

    // ---------- 等价的测试可观测面（替代对 provider 私有 map 的反射） ----------

    /** 未核销 challenge 的只读视图（供测试断言"机会式回收 / 容量 / 一次性"等价语义）。 */
    Map<String, ?> challengeView() {
        return challenges;
    }

    /** 已受理发送历史 key 的只读视图（供测试断言保留窗口剪枝与 phone key 容量）。 */
    Map<String, ?> acceptedSendsView() {
        return acceptedSends;
    }

    /** 进程内 challenge（一次性、带尝试上限）。 */
    private static final class Challenge {
        private final String phone;
        private final String code;
        private final Instant expiresAt;
        private final AtomicInteger attempts = new AtomicInteger();
        private volatile boolean consumed;

        private Challenge(String phone, String code, Instant expiresAt) {
            this.phone = phone;
            this.code = code;
            this.expiresAt = expiresAt;
        }
    }
}

package cn.yuanxin.mvp.web.sms;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.state.RedisFailures;
import cn.yuanxin.mvp.web.state.StateKeys;

import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * Redis 短信状态存储（{@code app.state.provider=redis}）：跨实例一致、重启不丢、fail closed。
 *
 * <p><b>全部原子步由 Lua 完成</b>（脚本位于 {@code src/main/resources/redis/sms-*.lua}，
 * 以不可变单例 {@link DefaultRedisScript} 加载；所有键经 {@link StateKeys} 构造，脚本访问的
 * 每个键都通过 {@code KEYS[]} 传入）：</p>
 * <ol>
 *   <li>创建 challenge：{@code HSET + EXPIRE} 一次完成且仅当键不存在；</li>
 *   <li>一次性核销：过期判定 + 尝试上限 + 摘要比较 + 计数或删除 + 返回手机号，单个脚本；</li>
 *   <li>节流预留：三窗口检查 + 占用 + 首次设 TTL，单个脚本；</li>
 *   <li>节流补偿：三窗口原子回退。</li>
 * </ol>
 *
 * <p><b>验证码明文绝不落 Redis</b>：只存 {@link StateKeys#codeDigest(String, String)}
 * （{@code sha256(code + "|" + challengeId)}，以 challengeId 为盐）。手机号是值中唯一的 PII
 * （核销成功需返回它建会话），绝不入键、绝不入日志。</p>
 *
 * <p><b>节流语义精化（有意，如实披露）</b>：旧实现只在发送<b>被受理后</b>计数，并靠进程内条带锁把
 * "预检 → 发送 → 记录" 串行化。跨实例无法用锁串行化，故本实现改为<b>原子预留 + 失败补偿</b>：
 * {@link #reserveSend} 原子占用三窗口名额（并发下绝不超发），远端发送未被受理时
 * {@link #releaseSend} 用另一脚本原子回退。稳态计数仍等于受理成功的发送数；差别仅在
 * "发送失败瞬间名额被短暂占用"，方向更严格。详见 {@code B-redis-state-migration.md} §4。</p>
 *
 * <p><b>失败计数 TTL</b>：限流计数键的 {@code INCR} 与 {@code if n==1 then EXPIRE} 在<b>同一脚本</b>内，
 * 因此绝不会留下 {@code TTL=-1} 的永不过期键；补偿使用 {@code EXISTS} 守卫，绝不制造负计数键。
 * challenge 的尝试计数是同哈希的 {@code att} 字段，随 challenge 键的 TTL 一起过期。</p>
 *
 * <p><b>fail closed</b>：所有后端访问经 {@link RedisFailures#call}；任何 Redis 连接/超时/服务端
 * 异常都翻译为 503 {@code DEPENDENCY_UNAVAILABLE}，绝不吞成 {@code Optional.empty()}（那会伪装成
 * 401 "验证码错误"），绝不回退内存制造伪成功。</p>
 *
 * <p><b>容量上限的等价处置（如实披露）</b>：内存实现用 {@code maxChallenges}/{@code maxTrackedPhones}
 * 计数上限对抗"内存只增不减"；Redis 后端每个键都有 TTL，该动因消失，故本实现不设应用层计数上限，
 * 改由键 TTL + 运维侧 Redis {@code maxmemory}/eviction 策略承载。若生产 Redis 触发 eviction，
 * 限流计数可能偏松（键被淘汰＝计数丢失）；生产应为该类键使用 {@code noeviction} 或独立实例并配置
 * 告警（设计文档 §5）。</p>
 */
public final class RedisSmsStateStore implements SmsStateStore {

    /** 核销成功时 Lua 返回值前缀，后接手机号；失败返回 {@code "!"}。返回值永远是字符串。 */
    private static final String CONSUME_SUCCESS_PREFIX = "+";
    private static final String CONSUME_FAILURE = "!";

    /**
     * 用于"空/空白验证码"的哨兵摘要：不等于任何 {@code sha256} 十六进制摘要，
     * 从而在 Lua 内表现为摘要不匹配（与旧实现 code==null 时匹配失败、尝试次数 +1 一致）。
     */
    private static final String NO_MATCH_DIGEST = "!no-match!";

    private static final DefaultRedisScript<Long> RESERVE_SCRIPT =
            script("redis/sms-rate-limit-reserve.lua", Long.class);
    private static final DefaultRedisScript<Long> COMPENSATE_SCRIPT =
            script("redis/sms-rate-limit-compensate.lua", Long.class);
    private static final DefaultRedisScript<Long> CREATE_SCRIPT =
            script("redis/sms-challenge-create.lua", Long.class);
    private static final DefaultRedisScript<String> CONSUME_SCRIPT =
            script("redis/sms-challenge-consume.lua", String.class);

    private final StringRedisTemplate template;
    private final StateKeys keys;
    private final SmsRiskProperties risk;

    public RedisSmsStateStore(StringRedisTemplate template, StateKeys keys, SmsRiskProperties risk) {
        this.template = template;
        this.keys = keys;
        this.risk = risk;
    }

    @Override
    public SendReservation reserveSend(String phone, Instant now) {
        SmsThrottleWindows.Snapshot windows = SmsThrottleWindows.compute(now);
        List<String> windowKeys = List.of(
                keys.smsRateLimit(phone, "m", windows.minuteBucket()),
                keys.smsRateLimit(phone, "h", windows.hourBucket()),
                keys.smsRateLimit(phone, "d", windows.dayBucket()));
        Long result = RedisFailures.call("sms-rate-limit-reserve", () -> template.execute(
                RESERVE_SCRIPT, windowKeys,
                String.valueOf(risk.maxPerMinute()), String.valueOf(risk.maxPerHour()),
                String.valueOf(risk.maxPerDay()),
                String.valueOf(windows.minuteTtlSeconds()), String.valueOf(windows.hourTtlSeconds()),
                String.valueOf(windows.dayTtlSeconds()),
                String.valueOf(windows.minuteRetryAfterSeconds()),
                String.valueOf(windows.hourRetryAfterSeconds()),
                String.valueOf(windows.dayRetryAfterSeconds())));
        if (result == null) {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                    "sms rate limit store returned no reservation result");
        }
        if (result == 0L) {
            return SendReservation.granted(phone, windowKeys);
        }
        return SendReservation.throttled(result);
    }

    @Override
    public void commitSend(SendReservation reservation, Instant now) {
        // 预留即计数：受理成功后无需再写（稳态计数 = 受理成功的发送数）。
    }

    @Override
    public void releaseSend(SendReservation reservation, boolean accepted) {
        if (accepted) {
            return;
        }
        @SuppressWarnings("unchecked")
        List<String> windowKeys = (List<String>) reservation.handle();
        RedisFailures.call("sms-rate-limit-compensate", () -> {
            template.execute(COMPENSATE_SCRIPT, windowKeys);
            return null;
        });
    }

    @Override
    public void createChallenge(String challengeId, String phone, String code, Instant now, int ttlSeconds) {
        String key = keys.smsChallenge(challengeId);
        String digest = StateKeys.codeDigest(code, challengeId);
        String expiresAtMillis = String.valueOf(now.plusSeconds(ttlSeconds).toEpochMilli());
        RedisFailures.call("sms-create-challenge", () -> {
            template.execute(CREATE_SCRIPT, List.of(key),
                    digest, phone, expiresAtMillis, String.valueOf(ttlSeconds));
            return null;
        });
    }

    @Override
    public Optional<String> consumeChallenge(String challengeId, String code, Instant now, int maxAttempts) {
        String key = keys.smsChallenge(challengeId);
        String digest = code == null || code.isBlank()
                ? NO_MATCH_DIGEST
                : StateKeys.codeDigest(code, challengeId);
        String result = RedisFailures.call("sms-consume-challenge", () -> template.execute(
                CONSUME_SCRIPT, List.of(key),
                digest, String.valueOf(now.toEpochMilli()), String.valueOf(maxAttempts)));
        if (result == null || !result.startsWith(CONSUME_SUCCESS_PREFIX)) {
            return Optional.empty();
        }
        return Optional.of(result.substring(CONSUME_SUCCESS_PREFIX.length()));
    }

    /** 从 classpath 加载不可变脚本单例（Spring 的脚本执行器会自动 EVALSHA → EVAL 回退）。 */
    private static <T> DefaultRedisScript<T> script(String location, Class<T> resultType) {
        DefaultRedisScript<T> script = new DefaultRedisScript<>();
        script.setLocation(new ClassPathResource(location));
        script.setResultType(resultType);
        return script;
    }
}

package cn.yuanxin.mvp.web.sms;

import cn.yuanxin.mvp.web.auth.SmsCodeProvider;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * 阿里云短信 {@link SmsCodeProvider} 真实实现（{@code app.sms.provider=aliyun}）。
 *
 * <p><b>issue 流程</b>：先本地节流<b>原子预留</b> → 生成 6 位随机码 → 调 {@link SmsSendGateway} →
 * <b>仅当平台受理（{@code Code=OK}）才创建 challenge 并返回</b>；发送未被受理时原子回退节流名额。
 * 任何失败都不创建 challenge，也<b>绝不</b>回退到 doubles 或返回一个"有效"挑战。失败映射：</p>
 * <ul>
 *   <li>{@link FailureKind#THROTTLED} → 429 {@code RATE_LIMITED}（带 {@code Retry-After} 头）；</li>
 *   <li>{@link FailureKind#CONFIGURATION} → 503 {@code DEPENDENCY_UNAVAILABLE}（消息注明不可重试）；</li>
 *   <li>{@link FailureKind#DEPENDENCY} → 503 {@code DEPENDENCY_UNAVAILABLE}（可退避重试，但短信非幂等）。</li>
 * </ul>
 *
 * <p><b>verify</b>：不存在/已过期/已核销/超过最大尝试次数 ⇒ {@code Optional.empty()}；
 * 正确且未超限 ⇒ 一次性核销并返回手机号（与 doubles 的 f02 401 语义一致）。</p>
 *
 * <p><b>状态与并发（BLOCKER 3 / IMPORTANT 8）</b>：challenge 与节流状态委托给 {@link SmsStateStore}：
 * {@link InMemorySmsStateStore}（{@code app.state.provider=memory}；逐字保留条带锁 + 容量上限的
 * 进程内语义）或 {@link RedisSmsStateStore}（{@code =redis}；Lua 原子步，跨实例一致）。
 * 因此本类自身<b>无共享可变状态</b>；"预检 → 发送 → 记录"的串行化与容量有界性由所选存储负责。</p>
 *
 * <p><b>节流语义精化（有意，如实披露）</b>：跨实例无法用进程内锁把"预检 → 远端发送 → 记录受理"
 * 串行化，Redis 后端改为<b>原子预留 + 失败补偿</b>：预留保证并发下绝不超发，发送未被受理时回退；
 * 稳态计数仍等于受理成功的发送数，差别仅在"发送失败瞬间名额被短暂占用"，方向更严格。
 * 详见 {@code backend/handoffs/B-redis-state-migration.md} §4。</p>
 *
 * <p><b>风控</b>：验证码由 {@link SecureRandom} 生成 6 位（会避开通用测试码 {@code 123456}）；
 * TTL、单 challenge 尝试上限、以及三窗口节流（默认对齐官方：同手机号 1 分钟 1 条 / 1 小时
 * 5 条 / 1 天 10 条，按 <b>UTC+8 自然窗口</b>）均由 {@link SmsRiskProperties} 配置。时间源为
 * 可注入 {@link Clock}（测试用固定/可变时钟，不用 sleep）；窗口归一在
 * {@link SmsThrottleWindows}，两个后端共用。</p>
 *
 * <p><b>脱敏</b>：日志与异常消息绝不包含完整手机号、验证码、challengeId 原文或凭据；
 * 手机号一律经 {@link SmsMasking#maskPhone(String)}。</p>
 */
public class AliyunSmsCodeProvider implements SmsCodeProvider {

    /** 通用 dev/test 固定码；真实模式绝不使用它，避免"万能码"误解。 */
    static final String DEV_FIXED_CODE = "123456";

    private static final int CODE_BOUND = 1_000_000;

    private final SmsSendGateway gateway;
    private final SmsRiskProperties risk;
    private final Clock clock;
    private final SmsStateStore store;
    private final SecureRandom random = new SecureRandom();

    public AliyunSmsCodeProvider(SmsSendGateway gateway, SmsRiskProperties risk) {
        this(gateway, risk, Clock.systemUTC());
    }

    public AliyunSmsCodeProvider(SmsSendGateway gateway, SmsRiskProperties risk, Clock clock) {
        this(gateway, risk, clock, new InMemorySmsStateStore(risk));
    }

    /** 可配置容量上限的构造器（测试用；生产默认走注入 {@link SmsStateStore} 的构造器）。 */
    public AliyunSmsCodeProvider(SmsSendGateway gateway, SmsRiskProperties risk, Clock clock,
                                 int maxChallenges, int maxTrackedPhones) {
        this(gateway, risk, clock, new InMemorySmsStateStore(risk, maxChallenges, maxTrackedPhones));
    }

    /** 生产/装配构造器：存储后端由 {@code app.state.provider} 决定。 */
    public AliyunSmsCodeProvider(SmsSendGateway gateway, SmsRiskProperties risk, Clock clock,
                                 SmsStateStore store) {
        this.gateway = gateway;
        this.risk = risk;
        this.clock = clock;
        this.store = store;
    }

    @Override
    public ChallengeOutcome issue(String phone, String purpose) {
        Instant now = clock.instant();
        // 原子预留：同手机号的"预检 → 发送 → 记录"在内存后端由条带锁串行化；
        // Redis 后端由单个 Lua 保证并发下绝不超发（失败时回退，见 finally）。
        SmsStateStore.SendReservation reservation = store.reserveSend(phone, now);
        if (!reservation.granted()) {
            throw rateLimited(reservation.retryAfterSeconds());
        }
        boolean accepted = false;
        try {
            String code = randomCode();
            SendResult result;
            try {
                result = gateway.send(phone, code);
            } catch (RuntimeException unexpected) {
                // 缝实现异常一律视为依赖失败；绝不回退替身、绝不签发 challenge。
                throw dependencyUnavailable("send exception " + unexpected.getClass().getSimpleName(),
                        "retry with backoff; sms send is not idempotent");
            }
            if (!result.accepted()) {
                throw mapFailure(result);
            }
            // 只统计已受理发送；失败/被节流拒绝的请求绝不计入。
            accepted = true;
            store.commitSend(reservation, now);
            String challengeId = newChallengeId();
            store.createChallenge(challengeId, phone, code, now, risk.challengeTtlSeconds());
            return new ChallengeOutcome(challengeId, risk.retryAfterSeconds());
        } finally {
            store.releaseSend(reservation, accepted);
        }
    }

    @Override
    public Optional<String> verify(String challengeId, String code) {
        if (challengeId == null || challengeId.isBlank()) {
            return Optional.empty();
        }
        return store.consumeChallenge(challengeId, code, clock.instant(), risk.maxVerifyAttempts());
    }

    private ApiException mapFailure(SendResult result) {
        String code = result.code() == null ? "<none>" : result.code();
        return switch (result.failureKind()) {
            case THROTTLED -> rateLimited(risk.retryAfterSeconds());
            case CONFIGURATION -> dependencyUnavailable(
                    "aliyun rejected configuration (code=" + code + "; not retryable)",
                    "fix the signature/template/permission configuration");
            case DEPENDENCY -> dependencyUnavailable(
                    "aliyun dependency failure (code=" + code + ")",
                    "retry with backoff; sms send is not idempotent");
        };
    }

    private static ApiException rateLimited(long retryAfterSeconds) {
        long retryAfter = Math.max(1, retryAfterSeconds);
        return new ApiException(ErrorCode.RATE_LIMITED,
                ErrorCode.RATE_LIMITED.defaultStatus().value(),
                "sms send throttled by local pre-check; retry after Retry-After seconds",
                Map.of("retryAfterSeconds", retryAfter),
                Map.of("Retry-After", String.valueOf(retryAfter)));
    }

    private static ApiException dependencyUnavailable(String detail, String guidance) {
        return new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                "sms provider unavailable: " + detail + "; " + guidance);
    }

    private String randomCode() {
        String code;
        do {
            code = String.format("%06d", random.nextInt(CODE_BOUND));
        } while (DEV_FIXED_CODE.equals(code));
        return code;
    }

    private String newChallengeId() {
        return UUID.randomUUID().toString().replace("-", "")
                + Long.toHexString(random.nextLong());
    }
}

package cn.yuanxin.mvp.web.sms;

import cn.yuanxin.mvp.web.state.AppStateProperties;
import cn.yuanxin.mvp.web.state.StateKeys;

import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.core.StringRedisTemplate;

/**
 * 阿里云短信状态存储的装配（仅 {@code app.sms.provider=aliyun} 且
 * {@code app.providers.mode != disabled} 时激活，与 {@link SmsProvidersConfig} 同门）。
 *
 * <p><b>按 {@code app.state.provider} 选择实现</b>：</p>
 * <ul>
 *   <li>{@code memory}（默认，{@code matchIfMissing=true}）：{@link InMemorySmsStateStore}，
 *       逐字保留旧的内存语义（仅供隔离测试 / doubles）；</li>
 *   <li>{@code redis}：{@link RedisSmsStateStore}，注入 {@code StringRedisTemplate} 与
 *       {@link StateKeys}（后者由 {@code RedisStateConfig} 在 {@code app.state.provider=redis}
 *       下提供）。</li>
 * </ul>
 *
 * <p><b>优先级不变</b>：{@code app.providers.mode=disabled} 最高——本配置与
 * {@link SmsProvidersConfig} 一样使用 {@link SmsProviderEnabledCondition}，因此能力显式关闭时
 * 本 bean 不装配，短信仍走 disabled 占位。</p>
 *
 * <p><b>只用 {@code StringRedisTemplate}</b>：{@code RedisTemplate<Object,Object>} 默认 JDK
 * 序列化，会让 Lua 收到二进制 key。</p>
 */
@Configuration(proxyBeanMethods = false)
@ConditionalOnProperty(name = "app.sms.provider", havingValue = "aliyun")
@Conditional(SmsProviderEnabledCondition.class)
@EnableConfigurationProperties(SmsRiskProperties.class)
public class SmsStateStoreConfig {

    /** 默认（未配置 {@code app.state.provider}）= 进程内实现，既有行为逐字不变。 */
    @Bean
    @ConditionalOnProperty(name = AppStateProperties.PROVIDER_KEY,
            havingValue = AppStateProperties.PROVIDER_MEMORY, matchIfMissing = true)
    public SmsStateStore inMemorySmsStateStore(SmsRiskProperties risk) {
        return new InMemorySmsStateStore(risk,
                InMemorySmsStateStore.DEFAULT_MAX_CHALLENGES,
                InMemorySmsStateStore.DEFAULT_MAX_TRACKED_PHONES);
    }

    /** {@code app.state.provider=redis}：跨实例一致的真实实现。 */
    @Bean
    @ConditionalOnProperty(name = AppStateProperties.PROVIDER_KEY,
            havingValue = AppStateProperties.PROVIDER_REDIS)
    public SmsStateStore redisSmsStateStore(StringRedisTemplate redis, StateKeys keys,
                                            SmsRiskProperties risk) {
        return new RedisSmsStateStore(redis, keys, risk);
    }
}

