import org.junit.platform.launcher.Launcher;
import org.junit.platform.launcher.LauncherDiscoveryRequest;
import org.junit.platform.launcher.core.LauncherDiscoveryRequestBuilder;
import org.junit.platform.launcher.core.LauncherFactory;
import org.junit.platform.launcher.listeners.SummaryGeneratingListener;

import java.io.PrintWriter;

import static org.junit.platform.engine.discovery.DiscoverySelectors.selectClass;

/** 独立 JUnit 启动器：仅用于本任务 javac 产物的手工验证，不属于交付源码。 */
public final class TestRunner {
    private TestRunner() {
    }

    public static void main(String[] args) throws Exception {
        LauncherDiscoveryRequest request = LauncherDiscoveryRequestBuilder.request()
                .selectors(selectClass(Class.forName(args[0])))
                .build();
        Launcher launcher = LauncherFactory.create();
        SummaryGeneratingListener listener = new SummaryGeneratingListener();
        launcher.execute(request, listener);
        PrintWriter out = new PrintWriter(System.out);
        listener.getSummary().printTo(out);
        listener.getSummary().printFailuresTo(out);
        out.flush();
        System.exit(listener.getSummary().getTotalFailureCount() > 0 ? 1 : 0);
    }
}

package cn.yuanxin.mvp.web.sms;

import cn.yuanxin.mvp.web.state.RedisTestSupport;
import cn.yuanxin.mvp.web.state.StateKeys;
import org.springframework.data.redis.core.StringRedisTemplate;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 判别力（负向证明）探针：证明"实现错了测试就失败"。只用于本任务的证据，
 * <b>不属于交付源码</b>；运行真实 Redis，使用独立随机前缀并彻底清理。
 *
 * <p>运行：{@code java -Dmvp.test.redis.url=redis://127.0.0.1:6399/5 ... NegativeProbe}</p>
 */
public final class NegativeProbe {

    private NegativeProbe() {
    }

    public static void main(String[] args) throws Exception {
        RedisTestSupport.RedisConnectionFactoryHolder holder = RedisTestSupport.connect();
        StringRedisTemplate template = holder.template();
        String prefix = RedisTestSupport.randomPrefix("smsneg");
        try {
            negativeATwoStepConsumeIsNotAtomic(template, prefix);
            positiveAAtomicConsumeHasExactlyOneWinner(template, prefix);
            negativeBBareIncrementLeavesNoTtl(template, prefix);
            positiveBReserveScriptAlwaysSetsTtl(template, prefix);
        } finally {
            long removed = RedisTestSupport.cleanup(template, prefix);
            System.out.println("CLEANUP_REMOVED=" + removed);
            System.out.println("CLEANUP_REMAINING=" + template.keys(prefix + "*").size());
            RedisTestSupport.close(holder);
        }
    }

    /** 负向 A：把核销拆成"先 GET 比较、再 DEL"两步 ⇒ 并发下必须出现 >= 2 个赢家。 */
    private static void negativeATwoStepConsumeIsNotAtomic(StringRedisTemplate template, String prefix)
            throws Exception {
        int threads = 32;
        String key = prefix + "probe:two-step:" + UUID.randomUUID().toString().replace("-", "");
        String digest = StateKeys.sha256Hex("correct-code");
        template.opsForValue().set(key, digest);

        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CyclicBarrier barrier = new CyclicBarrier(threads);
        AtomicInteger winners = new AtomicInteger();
        List<Callable<Void>> tasks = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            tasks.add(() -> {
                barrier.await(30, TimeUnit.SECONDS);
                String stored = template.opsForValue().get(key); // step 1: read
                if (stored != null && stored.equals(digest)) {
                    winners.incrementAndGet();
                    template.delete(key); // step 2: delete (NOT atomic with the read)
                }
                return null;
            });
        }
        List<Future<Void>> futures = pool.invokeAll(tasks, 60, TimeUnit.SECONDS);
        pool.shutdownNow();
        for (Future<Void> future : futures) {
            future.get();
        }
        System.out.println("NEGATIVE_A_TWO_STEP_WINNERS=" + winners.get()
                + " (expected >= 2: broken non-atomic consume signs multiple sessions)");
        if (winners.get() < 2) {
            System.out.println("NEGATIVE_A_NOT_DISCRIMINATING=the negative control did not reproduce"
                    + " the race in this run");
        }
    }

    /** 正向 A：同一并发场景下，真实原子 Lua 核销恰好 1 个赢家。 */
    private static void positiveAAtomicConsumeHasExactlyOneWinner(StringRedisTemplate template, String prefix)
            throws Exception {
        int threads = 32;
        StateKeys keys = new StateKeys(prefix);
        RedisSmsStateStore store = new RedisSmsStateStore(template, keys,
                new SmsRiskProperties(null, null, null, null, null, null));
        String challengeId = "probe" + UUID.randomUUID().toString().replace("-", "");
        Instant now = Instant.parse("2026-01-01T00:00:00Z");
        store.createChallenge(challengeId, "+8610000000000", "246810", now, 300);

        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CyclicBarrier barrier = new CyclicBarrier(threads);
        AtomicInteger winners = new AtomicInteger();
        List<Callable<Void>> tasks = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            tasks.add(() -> {
                barrier.await(30, TimeUnit.SECONDS);
                if (store.consumeChallenge(challengeId, "246810", now.plusSeconds(1), 5).isPresent()) {
                    winners.incrementAndGet();
                }
                return null;
            });
        }
        List<Future<Void>> futures = pool.invokeAll(tasks, 60, TimeUnit.SECONDS);
        pool.shutdownNow();
        for (Future<Void> future : futures) {
            future.get();
        }
        System.out.println("POSITIVE_A_ATOMIC_WINNERS=" + winners.get() + " (expected exactly 1)");
    }

    /** 负向 B：裸 INCR 后"崩溃"（未发 EXPIRE）⇒ 留下 TTL=-1 的永不过期键，被 TTL>0 断言逮到。 */
    private static void negativeBBareIncrementLeavesNoTtl(StringRedisTemplate template, String prefix) {
        String key = prefix + "probe:bare-incr:" + UUID.randomUUID().toString().replace("-", "");
        template.opsForValue().increment(key); // step 1: INCR
        // step 2 (EXPIRE) simulated as crashing/never executed
        Long ttl = template.getExpire(key);
        boolean caught = ttl != null && ttl < 0;
        System.out.println("NEGATIVE_B_BARE_INCR_TTL=" + ttl
                + " caughtByTtlGreaterThanZeroAssertion=" + caught);
    }

    /** 正向 B：真实预留脚本在同一脚本内 INCR + 首次 EXPIRE ⇒ TTL 恒 > 0。 */
    private static void positiveBReserveScriptAlwaysSetsTtl(StringRedisTemplate template, String prefix) {
        StateKeys keys = new StateKeys(prefix);
        RedisSmsStateStore store = new RedisSmsStateStore(template, keys,
                new SmsRiskProperties(null, null, null, null, null, null));
        Instant now = Instant.parse("2026-01-01T00:00:00Z");
        store.reserveSend("+8610000000000", now);
        SmsThrottleWindows.Snapshot windows = SmsThrottleWindows.compute(now);
        String minuteKey = keys.smsRateLimit("+8610000000000", "m", windows.minuteBucket());
        System.out.println("POSITIVE_B_RESERVE_TTL=" + template.getExpire(minuteKey) + " (expected > 0)");
    }
}

